# AI Office v2.4 Part E Discord Worker Service Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
if(-not(Test-Path -LiteralPath $Repository -PathType Container)){throw "AI Office repository not found."}
Set-Location $Repository
$Timestamp=Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory=Join-Path $Repository ("workspace\installer-backups\v2.4-part-e-"+$Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force|Out-Null
function Write-EmbeddedFile{param([string]$RelativePath,[string]$Base64Content);$Destination=Join-Path $Repository $RelativePath;$Parent=Split-Path -Parent $Destination;if($Parent-and-not(Test-Path $Parent)){New-Item -ItemType Directory -Path $Parent -Force|Out-Null};if(Test-Path $Destination){$BackupPath=Join-Path $BackupDirectory $RelativePath;$BackupParent=Split-Path -Parent $BackupPath;if($BackupParent-and-not(Test-Path $BackupParent)){New-Item -ItemType Directory -Path $BackupParent -Force|Out-Null};Copy-Item $Destination $BackupPath -Force};[IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content));Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green}
Write-EmbeddedFile -RelativePath "config\discord-office\worker-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\discord-office\state\worker-state.json" -Base64Content "ewogICJzdGF0dXMiOiAic3RvcHBlZCIsCiAgInN0YXJ0ZWRfYXQiOiAiIiwKICAibGFzdF9wb2xsX2F0IjogIiIsCiAgImxhc3RfbWVzc2FnZV9pZCI6ICIiLAogICJwcm9jZXNzZWRfbWVzc2FnZXMiOiAwLAogICJlcnJvcnMiOiAwLAogICJsYXN0X2Vycm9yIjogIiIsCiAgInVwZGF0ZWRfYXQiOiAiIgp9Cg=="
Write-EmbeddedFile -RelativePath "scripts\discord-office\Get-AIOfficeDiscordWorkerState.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Start-AIOfficeDiscordWorker.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Stop-AIOfficeDiscordWorker.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Invoke-AIOfficeDiscordWorker.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Install-AIOfficeDiscordWorkerStartup.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Test-AIOfficeDiscordWorker.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.4-Part-E-Discord-Worker-Service.md" -Base64Content ""
$ScriptPaths=Get-ChildItem "E:\AI\AI-Office\scripts\discord-office\*.ps1" -File
foreach($ScriptPath in $ScriptPaths){$Tokens=$null;$ParseErrors=$null;[System.Management.Automation.Language.Parser]::ParseFile($ScriptPath.FullName,[ref]$Tokens,[ref]$ParseErrors)|Out-Null;if($ParseErrors.Count-gt0){throw ("Syntax error in "+$ScriptPath.FullName+": "+(($ParseErrors|ForEach-Object{$_.Message})-join"; "))}}
Write-Host ""
Write-Host "AI Office v2.4 Part E Discord Worker Service installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan